--
-- Table structure for table `adminsignuprequest`
--

DROP TABLE IF EXISTS `adminsignuprequest`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `adminsignuprequest` (
  `request_id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `requested_yurtid` int(11) NOT NULL,
  `status` enum('pending','approved','rejected') DEFAULT 'pending',
  `requested_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `reviewed_by` int(11) DEFAULT NULL COMMENT 'Super-admin who reviewed',
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL COMMENT 'Review notes or rejection reason',
  PRIMARY KEY (`request_id`),
  UNIQUE KEY `username` (`username`),
  KEY `requested_yurtid` (`requested_yurtid`),
  KEY `reviewed_by` (`reviewed_by`),
  KEY `idx_signup_status` (`status`,`requested_at`),
  CONSTRAINT `adminsignuprequest_ibfk_1` FOREIGN KEY (`requested_yurtid`) REFERENCES `yurt` (`yurtid`) ON DELETE CASCADE,
  CONSTRAINT `adminsignuprequest_ibfk_2` FOREIGN KEY (`reviewed_by`) REFERENCES `user` (`accountid`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Admin signup approval queue';
/*!40101 SET character_set_client = @saved_cs_client */;

