DROP TABLE IF EXISTS `attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `attendance` (
  `studentid` int(11) NOT NULL,
  `yurtid` int(11) NOT NULL DEFAULT 1,
  `date` date NOT NULL,
  `attendance_type_name` varchar(45) NOT NULL,
  `program_name` varchar(45) NOT NULL,
  `sebep` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`studentid`,`date`,`program_name`),
  KEY `fk_Attendance_AttendanceType1_idx` (`attendance_type_name`),
  KEY `fk_Attendance_Program1_idx` (`program_name`),
  KEY `idx_attendance_yurt` (`yurtid`),
  KEY `idx_attendance_yurt_date_program` (`yurtid`,`date`,`program_name`),
  CONSTRAINT `fk_Attendance_AttendanceType1` FOREIGN KEY (`attendance_type_name`) REFERENCES `attendancetype` (`attendance_type_name`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_Attendance_Program1` FOREIGN KEY (`program_name`) REFERENCES `program` (`program_name`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_Attendance_Student1` FOREIGN KEY (`studentid`) REFERENCES `student` (`studentid`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `fk_attendance_yurt` FOREIGN KEY (`yurtid`) REFERENCES `yurt` (`yurtid`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;
